const curRaw = $input.first().json;
const current = curRaw && curRaw.id ? curRaw : (curRaw && curRaw.data && curRaw.data.id ? curRaw.data : null);
const INPOST = 215500877;
const WORKSPACE = 3825058;
const TZ = 'Europe/Warsaw';

function warsawParts(date) {
  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone: TZ,
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit',
    hour12: false,
  }).formatToParts(date);
  const g = (t) => {
    const v = parts.find((p) => p.type === t)?.value || '0';
    return Number(v === '24' ? '0' : v);
  };
  return { y: g('year'), m: g('month'), d: g('day'), H: g('hour'), M: g('minute'), S: g('second') };
}
function warsawLocalToUtcMs(y, m, d, H = 0, M = 0, S = 0) {
  let utc = Date.UTC(y, m - 1, d, H, M, S);
  for (let i = 0; i < 4; i++) {
    const p = warsawParts(new Date(utc));
    const asUtc = Date.UTC(p.y, p.m - 1, p.d, p.H, p.M, p.S);
    const target = Date.UTC(y, m - 1, d, H, M, S);
    utc += target - asUtc;
  }
  return utc;
}
function addWarsawDays(y, m, d, days) {
  const noon = warsawLocalToUtcMs(y, m, d, 12, 0, 0) + days * 24 * 3600 * 1000;
  const p = warsawParts(new Date(noon));
  return [p.y, p.m, p.d];
}

const has = !!(current && current.id);
const isCandidate = has
  && Number(current.project_id || 0) === INPOST
  && String(current.description || '') === 'Work';

const now = new Date();
const p = warsawParts(now);
const before_7am = p.H < 7;
let wy = p.y, wm = p.m, wd = p.d;
if (before_7am) [wy, wm, wd] = addWarsawDays(p.y, p.m, p.d, -1);
const windowStartMs = warsawLocalToUtcMs(wy, wm, wd, 7, 0, 0);
const [ey, em, ed] = addWarsawDays(wy, wm, wd, 1);
const windowEndMs = warsawLocalToUtcMs(ey, em, ed, 7, 0, 0);

return [{ json: {
  skip: !isCandidate,
  current,
  before_7am,
  window_start_iso: new Date(windowStartMs).toISOString(),
  window_end_iso: new Date(windowEndMs).toISOString(),
  window_start_ms: windowStartMs,
  window_end_ms: windowEndMs,
  inpost_project_id: INPOST,
  workspace_id: WORKSPACE,
}}];

const prep = $('Prepare Split Context').first().json;
const entries = $input.all().map((i) => i.json).filter((e) => e && e.id);
return [{ json: { ...prep, day_entries: entries } }];

const tags = $input.all().map((i) => i.json).filter((t) => t && t.id && t.name !== '__none__');
const oh = tags.find((t) => String(t.name || '').trim() === 'OH');
if (oh) return [{ json: { oh_tag_id: Number(oh.id), need_create: false } }];
return [{ json: { oh_tag_id: null, need_create: true } }];

const prep = $('Prepare Split Context').first().json;
if (prep.skip) return [{ json: { skip: true, reason: 'not_running_work' } }];

const entry = prep.current;
const INPOST = Number(prep.inpost_project_id);
const THRESHOLD = 8 * 3600;
const OH_DESC = 'Work OverHours';

let oh_tag_id = null;
try {
  const ensured = $('Ensure OH Tag').first().json;
  if (ensured && ensured.oh_tag_id) oh_tag_id = Number(ensured.oh_tag_id);
} catch (e) {}
try {
  if (!oh_tag_id) {
    const created = $('Create OH Tag').first().json;
    if (created && created.id) oh_tag_id = Number(created.id);
  }
} catch (e) {}

function clampOverlapSec(startIso, stopIso, winStart, winEnd, nowMs) {
  const start = Date.parse(startIso);
  if (!Number.isFinite(start)) return 0;
  let end = stopIso ? Date.parse(stopIso) : nowMs;
  if (!Number.isFinite(end)) end = nowMs;
  const a = Math.max(start, winStart);
  const b = Math.min(end, winEnd);
  return Math.max(0, Math.floor((b - a) / 1000));
}

const entries = Array.isArray($('Normalize Day Entries').first().json.day_entries)
  ? $('Normalize Day Entries').first().json.day_entries : [];
const nowMs = Date.now();
const winStart = Number(prep.window_start_ms);
const winEnd = Number(prep.window_end_ms);
let sum = 0;
const seen = new Set();
for (const e of entries) {
  if (Number(e.project_id || 0) !== INPOST) continue;
  seen.add(String(e.id));
  const running = !e.stop && Number(e.duration) < 0;
  sum += clampOverlapSec(e.start, running ? null : e.stop, winStart, winEnd, nowMs);
}
if (entry && entry.id && Number(entry.project_id || 0) === INPOST && !seen.has(String(entry.id))) {
  sum += clampOverlapSec(entry.start, null, winStart, winEnd, nowMs);
}

const need_split = prep.before_7am || sum >= THRESHOLD;
if (!need_split) {
  return [{ json: { skip: true, reason: 'under_threshold', sum_sec: sum } }];
}
if (String(entry.description || '') === OH_DESC) {
  return [{ json: { skip: true, reason: 'already_overhours', sum_sec: sum } }];
}

return [{ json: {
  skip: false,
  need_split: true,
  stop_id: entry.id,
  stop_wid: entry.workspace_id || prep.workspace_id,
  workspace_id: Number(prep.workspace_id),
  project_id: INPOST,
  description: OH_DESC,
  tag_ids: oh_tag_id ? [oh_tag_id] : [],
  start_iso: new Date().toISOString(),
  sum_sec: sum,
  before_7am: !!prep.before_7am,
}}];
